CREATE DATABASE IF NOT EXISTS `macroeconomics_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `macroeconomics_db`;

-- Table structure

CREATE TABLE `countries` (
  `country_id` int NOT NULL AUTO_INCREMENT,
  `country_name` varchar(100) NOT NULL,
  `iso_code` varchar(5) NOT NULL,
  PRIMARY KEY (`country_id`),
  UNIQUE KEY `iso_code` (`iso_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `sources` (
  `source_id` int NOT NULL AUTO_INCREMENT,
  `source_name` varchar(100) NOT NULL,
  PRIMARY KEY (`source_id`),
  UNIQUE KEY `source_name` (`source_name`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `indicators` (
  `indicator_id` int NOT NULL AUTO_INCREMENT,
  `indicator_name` varchar(100) NOT NULL,
  `unit` varchar(20) NOT NULL,
  `source_id` int NOT NULL,
  PRIMARY KEY (`indicator_id`),
  KEY `source_id` (`source_id`),
  CONSTRAINT `indicators_ibfk_1` FOREIGN KEY (`source_id`) REFERENCES `sources` (`source_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `periods` (
  `period_id` int NOT NULL AUTO_INCREMENT,
  `year` int NOT NULL,
  `quarter` tinyint NOT NULL,
  PRIMARY KEY (`period_id`),
  UNIQUE KEY `year` (`year`,`quarter`),
  CONSTRAINT `periods_chk_1` CHECK ((`quarter` in (1,2,3,4)))
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `macro_values` (
  `value_id` int NOT NULL AUTO_INCREMENT,
  `country_id` int NOT NULL,
  `indicator_id` int NOT NULL,
  `period_id` int NOT NULL,
  `value` decimal(12,4) DEFAULT NULL,
  PRIMARY KEY (`value_id`),
  UNIQUE KEY `country_id` (`country_id`,`indicator_id`,`period_id`),
  KEY `indicator_id` (`indicator_id`),
  KEY `period_id` (`period_id`),
  CONSTRAINT `macro_values_ibfk_1` FOREIGN KEY (`country_id`) REFERENCES `countries` (`country_id`),
  CONSTRAINT `macro_values_ibfk_2` FOREIGN KEY (`indicator_id`) REFERENCES `indicators` (`indicator_id`),
  CONSTRAINT `macro_values_ibfk_3` FOREIGN KEY (`period_id`) REFERENCES `periods` (`period_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1535 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

